reference.py:
from abc import ABC, abstractmethod

class Writer(ABC):
    @abstractmethod
    def write(self, line): ...

class ReportService:
    def __init__(self, writer):
        self.writer = writer

    def publish(self, items):
        self.writer.write(f"Report: {len(items)} items")
        for item in items:
            self.writer.write(f"- {item}")

class InMemoryWriter(Writer):
    def __init__(self):
        self.lines = []

    def write(self, line):
        self.lines.append(line)
